BEGIN;
CREATE TEMP TABLE analyst_fixture AS SELECT p.user_id owner_id,p.partner_user_id partner_id,gen_random_uuid() account_id,gen_random_uuid() tx_id FROM partner_links p WHERE p.status='active' LIMIT 1;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM analyst_fixture) THEN RAISE EXCEPTION 'Active pair required'; END IF; END $$;
GRANT SELECT ON analyst_fixture TO authenticated;
INSERT INTO accounts(id,user_id,name,type,current_balance,currency) SELECT account_id,owner_id,'Analyst rollback fixture','checking',1000,'USD' FROM analyst_fixture;
INSERT INTO transactions(id,user_id,account_id,name,amount,date,category,cash_flow_type,is_one_time_expense) SELECT tx_id,owner_id,account_id,'Rollback expense',100,current_date,'Other','operating',false FROM analyst_fixture;
UPDATE finance_allocations SET owner_pct=40,balance_pct=NULL WHERE account_id IN (SELECT account_id FROM analyst_fixture) AND effective_from='0001-01-01';
SET LOCAL ROLE authenticated;
DO $$ DECLARE t record;blocked boolean;goal uuid;batch uuid;cnt integer;expected jsonb; BEGIN
 SELECT * INTO t FROM analyst_fixture;
 PERFORM set_config('request.jwt.claim.sub',t.owner_id::text,true);
 PERFORM finance_account_transition(t.account_id,'0001-01-01',current_date-30,0,50,0,100,true,'Partner then shared');
 IF (SELECT owner_pct FROM finance_allocations WHERE account_id=t.account_id AND effective_from='0001-01-01')<>0 THEN RAISE EXCEPTION 'Partner history lost'; END IF;
 IF (SELECT balance_pct FROM finance_allocations WHERE account_id=t.account_id AND effective_from=current_date-30)<>100 THEN RAISE EXCEPTION 'Balance ownership conflated'; END IF;
 PERFORM finance_schedule(ARRAY[t.account_id],current_date+30,25,true,'Future expense split');
 IF (SELECT balance_pct FROM finance_allocations WHERE account_id=t.account_id AND effective_from=current_date+30)<>100 THEN RAISE EXCEPTION 'Expense-only change changed balance'; END IF;
 PERFORM finance_category_split(t.account_id,'Other',current_date-30,70);
 goal:=finance_reserve_goal(t.account_id,'Rollback goal',700,900,NULL);
 blocked:=false;BEGIN PERFORM finance_reserve_goal(t.account_id,'Overfunded',400,500,NULL);EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Overfunding allowed'; END IF;
 blocked:=false;BEGIN INSERT INTO finance_documents(owner_id,kind,name,payload) VALUES(t.owner_id,'goal','Bypass','{}');EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Goal bypass allowed'; END IF;
 SELECT jsonb_build_object('category',category,'cash_flow_type',cash_flow_type,'is_one_time_expense',is_one_time_expense,'income_type',income_type) INTO expected FROM transactions WHERE id=t.tx_id;
 batch:=finance_apply_review(jsonb_build_array(jsonb_build_object('id',t.tx_id,'expected',expected,'patch',jsonb_build_object('category','Shopping'))));
 IF (SELECT category FROM transactions WHERE id=t.tx_id)<>'Shopping' THEN RAISE EXCEPTION 'Review failed'; END IF;
 PERFORM finance_undo_review(batch);
 IF (SELECT category FROM transactions WHERE id=t.tx_id)<>'Other' THEN RAISE EXCEPTION 'Undo failed'; END IF;
 cnt:=finance_import_statement(t.account_id,jsonb_build_array(jsonb_build_object('date',current_date,'name','CSV fixture','amount',12,'key',repeat('a',64))));
 IF cnt<>1 THEN RAISE EXCEPTION 'Import failed';END IF;
 cnt:=finance_import_statement(t.account_id,jsonb_build_array(jsonb_build_object('date',current_date,'name','CSV fixture','amount',12,'key',repeat('a',64))));
 IF cnt<>0 THEN RAISE EXCEPTION 'Duplicate import accepted';END IF;
 INSERT INTO finance_documents(owner_id,kind,name,payload) VALUES(t.owner_id,'close','Rollback close','{}');
 UPDATE finance_documents SET name='Changed close' WHERE owner_id=t.owner_id AND name='Rollback close';
 GET DIAGNOSTICS cnt=ROW_COUNT;IF cnt<>0 THEN RAISE EXCEPTION 'Close editable';END IF;
 PERFORM finance_share_account(t.account_id,true,current_date-60,NULL);
 PERFORM set_config('request.jwt.claim.sub',t.partner_id::text,true);
 IF EXISTS(SELECT 1 FROM finance_documents WHERE id=goal) THEN RAISE EXCEPTION 'Private plan exposed';END IF;
 IF NOT EXISTS(SELECT 1 FROM finance_balance_observations WHERE account_id=t.account_id) THEN RAISE EXCEPTION 'Shared observations unavailable';END IF;
 blocked:=false;BEGIN PERFORM finance_account_transition(t.account_id,'0001-01-01',current_date,100,50,100,100,true,'Unauthorized');EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Partner modified account';END IF;
 blocked:=false;BEGIN PERFORM finance_import_statement(t.account_id,'[]');EXCEPTION WHEN raise_exception THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Partner imported to account';END IF;
 PERFORM set_config('request.jwt.claim.sub',t.owner_id::text,true);
 PERFORM finance_end_arrangements(current_date);
 IF EXISTS(SELECT 1 FROM finance_allocations WHERE account_id=t.account_id AND effective_from>=current_date AND (owner_pct<>100 OR included OR balance_pct<>100)) THEN RAISE EXCEPTION 'Separation failed'; END IF;
 IF (SELECT owner_pct FROM finance_allocations WHERE account_id=t.account_id AND effective_from='0001-01-01')<>0 THEN RAISE EXCEPTION 'Separation rewrote history';END IF;
END $$;
RESET ROLE;
UPDATE finance_allocations SET owner_pct=40,balance_pct=NULL WHERE account_id IN (SELECT account_id FROM analyst_fixture) AND effective_from=current_date;
SET LOCAL ROLE authenticated;
DO $$ DECLARE t record; BEGIN SELECT * INTO t FROM analyst_fixture;PERFORM set_config('request.jwt.claim.sub',t.owner_id::text,true);PERFORM finance_end_arrangements(current_date);IF (SELECT balance_pct FROM finance_allocations WHERE account_id=t.account_id AND effective_from=current_date)<>40 THEN RAISE EXCEPTION 'Same-day legacy balance ownership changed';END IF; END $$;
RESET ROLE;
ROLLBACK;
SELECT 'PASS: account phases, independent balances, future cutoff, owner-only changes, private plans, immutable summaries, goal limits, rule apply/undo, duplicate-safe imports. All fixtures rolled back.' AS result;
